#include <iostream>

struct CantidadInvalida {};
struct SumaExcesiva {};

class Cantidad {
public:
    Cantidad() = default;
    explicit Cantidad(int valor) : unidades_{valor} {
        if (valor < 0 || valor > 1000) { throw CantidadInvalida{}; }
    }
    int valor() const noexcept { return unidades_; }
    Cantidad operator+(const Cantidad& otra) const;
    Cantidad& operator+=(const Cantidad& otra);
private:
    int unidades_ = 0;
};
Cantidad Cantidad::operator+(const Cantidad& otra) const {
    const int suma = unidades_ + otra.unidades_;
    if (suma > 1000) { throw SumaExcesiva{}; }
    return Cantidad{suma};
}
Cantidad& Cantidad::operator+=(const Cantidad& otra) {
    // Obtén la suma válida antes de sustituir el destino y devuelve ese destino.
    (void)otra;
    return *this;
}
int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Cantidad valores[3]{Cantidad{200}, Cantidad{300}, Cantidad{100}};
    for (int i = 0; i < ordenes; ++i) {
        int op = 0, destino = 0, a = 0, b = 0;
        if (!(std::cin >> op >> destino >> a >> b)) { return 1; }
        std::cout << "Antes:" << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor();
        const char* estado = "Operacion";
        int mismo = -1;
        try {
            if (op >= 1 && op <= 3) {
                if (destino < 0 || destino > 2) {
                    estado = "Indice";
                } else if (op == 1) {
                    valores[destino] = Cantidad{a};
                    estado = "Aceptada";
                } else if (a < 0 || a > 2 || (op == 3 && (b < 0 || b > 2))) {
                    estado = "Indice";
                } else if (op == 2) {
                    Cantidad& r = (valores[destino] += valores[a]);
                    mismo = (&r == &valores[destino]);
                    estado = "Aceptada";
                } else {
                    Cantidad& r = ((valores[destino] += valores[a]) += valores[b]);
                    mismo = (&r == &valores[destino]);
                    estado = "Aceptada";
                }
            }
        } catch (const CantidadInvalida&) {
            estado = "Rango";
        } catch (const SumaExcesiva&) {
            estado = "Suma";
        }
        std::cout << ";Estado:" << estado << ";Mismo:" << mismo << ";Ahora:"
                  << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor() << '\n';
    }
    std::cout << "Final:" << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor();
    return 0;
}

